pub const TRAJECTORY_REGION_INSTRUCTIONS: &str = r#"【軌跡・領域問題専用の解答規則】
この追加指示は、入力が高校数学の軌跡または領域を求める問題である場合だけ適用してください。他分野の解答形式は変更しないでください。

【最初に問題の型を判定する】
解答を書き始める前に、次のどの型かを判定し、該当する規則だけを適用してください。
1. 点の軌跡または点の存在範囲そのものを最終的に求める問題
2. 動く線分・直線・円・図形が通過または被覆する領域や、曲線族の包絡線を求める問題
3. 領域の決定が途中段階で、その後に面積・体積・確率・最大最小などを求める複合問題
1では$P(x,y)\in R\Longleftrightarrow\cdots$から始まる一続きの同値変形を必須とします。2と3でも、$xy$平面上の任意の点の領域への所属条件をパラメータの存在条件として自然に表せる場合は、その領域決定部分で所属条件から始まる同値変形を優先してください。特に動く線分では、補間パラメータによって線分上の条件を正確に保持できるため、この方法を最初に検討してください。同値変形が著しく不自然または冗長になる場合だけ、包絡線や最大・最小などによる通常の解法へ切り替えてください。2と3の解答全体を形式だけのために1本の同値変形へ押し込んではいけません。

【問題文の記号を保持する】
問題文ですでに点、直線、円、図形などの名前が定義されている場合は、その記号を最後までそのまま使用してください。問題文で中点が$M$なら$M(x,y)$、動点が$Q$なら$Q(x,y)$とし、形式統一のために$P$など別の点名へ変更してはいけません。
定義済みの対象へ不要な別名を付けること、同じ対象を複数の記号で表すこと、問題文から明らかな対象を別の動点として再定義することを禁止します。
新しい記号は、計算に本当に必要な補助変数と、未定義の軌跡・領域の集合を表す記号に限って導入してください。求める点の名前が問題文にない場合でも、動く線分や図形の領域を求めるために不要な点$X(x,y)$を形式上導入してはいけません。ただし、領域への所属をパラメータの存在条件として記述するために$xy$平面上の任意の点を置くことは、必要な記号の導入です。この場合は、問題文ですでに$P,Q$が使われていれば$X(x,y)$、$X$も使われていれば$Y(x,y)$など、既存の記号と衝突しない点名を一つだけ用いてください。判定前にその点が領域へ属すると仮定してはいけません。

【求める点の座標を冒頭で明示する】
この節は、点の軌跡または点の存在範囲を求め、後でその点を$M(x,y)$等と表す場合だけ適用してください。問題文で求める点が$M$と定義されている場合は、解答の冒頭を原則として「求める軌跡を$R$とし、中点$M$の座標を$M(x,y)$とする。」の形にしてください。中点以外の点では問題文で定義された点の名称に合わせてください。
「求める軌跡を$R$とする」または「求める領域を$R$とする」だけで終え、後の同値変形で初めて$M(x,y)$などを使用してはいけません。後で使用する求める点の座標は、必要最小限の準備計算より前に必ず設定してください。
座標設定でも問題文の点名を変更してはいけません。点名と座標を等号で結ばず、「中点$M$の座標を$M(x,y)$とする」のように書いてください。
問題文ですでに$P(p,q)$のように点名と座標文字が定義されている場合は、その座標文字も保持し、$P(x,y)$などへ変更してはいけません。この場合は、冒頭で同じ座標設定を重複して書かず、問題文の$P(p,q)$をそのまま使用してください。

【集合と判別式】
問題文ですでに軌跡・領域の記号が定義されている場合は、実際の記号衝突が起きない限りその記号を保持してください。例えば、問題文で線分が通過する部分を$D$と定義し、その解答で判別式を使用しないなら、領域を最後まで$D$と表してください。将来使うかもしれない判別式との衝突を先回りして$D$を$R$へ変更してはいけません。
問題文で集合記号が未定義で、点の軌跡または存在範囲そのものを求める場合は$R$を使用してください。問題文で$R$が別の意味に使われている場合は$S$、$L$、$\mathcal{R}$など重複しない記号を使用してください。
2次方程式の判別式を実際に使用する場合だけ、判別式には必ず$D$を使用してください。判別式に$\Delta$を使用してはいけません。問題文の領域$D$と判別式$D$が同じ解答内で実際に衝突する場合に限り、判別式の$D$を維持して領域側を$R$等へ変更し、冒頭で「領域$D$を以下$R$と表す」等と一度だけ明示してください。実際に存在しない衝突を避けるための改名は禁止します。

【点の軌跡・存在範囲が最終目的の場合は、解答本体を最初から同値変形にする】
この節から【存在条件の書き方】までの規則は、点の軌跡または点の存在範囲そのものが最終的な問いである場合に適用してください。動く線分・図形の通過領域や複合問題へ無条件に適用してはいけません。
最初に必要な文字と集合を定義し、後の同値変形で直接使う必要最小限の準備計算だけを示してください。準備計算として許されるのは、交点座標が満たす方程式、判別式$D$、解と係数の関係、点の座標をパラメータで表すために直接必要な式などです。
準備計算の段階で、求める軌跡・領域の最終的な$x,y$の条件まで導いてはいけません。同じ計算を準備計算と同値変形の両方へ重複して書いてはいけません。

この型では、準備計算の直後から、問題文で求める点の名前を用いて、解答本体を必ず次の形の一続きの同値変形として開始してください。
\[
\begin{aligned}
M(x,y)\in R
&\Longleftrightarrow \text{問題文の幾何学的条件}\\
&\Longleftrightarrow \text{パラメータや補助変数を、その存在条件とともに用いた条件}\\
&\Longleftrightarrow \text{$x,y$だけで表された最終条件}
\end{aligned}
\]
上の$M$は形式例です。必ず問題文で定義された点名へ置き換えてください。最終的な$x,y$の条件は、この同値変形の中で初めて導いてください。
同値変形は解答末尾の要約ではなく、解答本体そのものにしてください。通常の一方向の論証で最終条件まで求めた後に同じ内容を同値変形で再掲してはいけません。
必要最小限の準備計算が終わったら、「以上の準備のもとで、軌跡の条件を同値変形すると」などの接続文を挟まず、直ちに$M(x,y)\in R\Longleftrightarrow\cdots$から始めてください。
「以上の準備のもとで、軌跡の条件を同値変形すると」「以上を一続きの同値変形でまとめると」「以上を同値変形で表すと」「ここまでの結果をまとめると」「以上の議論をまとめると」「これを同値変形の形で書けば」を使用してはいけません。読点が「、」「，」「,」のいずれであっても同様です。

【必要性と十分性を分離しない】
点の軌跡・存在範囲を一続きの同値変形で処理する場合は、「まず必要条件を求める」「逆に」「必要性」「十分性」「十分性を確認する」「この条件を満たす点が実際に存在することを示す」という構成を使用してはいけません。
パラメータの存在条件、実数条件、範囲条件、符号条件を保ったまま消去し、必要性と十分性を一続きの同値変形で同時に処理してください。同値変形が最終条件まで到達した後に、独立した逆の確認を追加してはいけません。

【存在条件の書き方】
この節は、点の軌跡・存在範囲を同値変形し、その中でパラメータの存在を述べる場合に適用してください。
$\exists$、$\forall$などの量化記号を使用してはいけません。「これらを満たす実数$k$が存在する」「$y=f(\theta)$となる実数$\theta$が存在する」などの日本語を使用し、パラメータを消去するまで存在条件を省略してはいけません。
複数の条件を満たす実数の存在を述べる場合は、必ず次のLaTeX構造を使用してください。
\[
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
|k|&>4\\
x&=-\dfrac{3k}{8}\\
y&=-\dfrac{k}{8}
\end{aligned}
\right.\\
\text{を満たす実数 }k\text{ が存在する」}
\end{gathered}
\]
条件が2つ以上ある場合は必ず左波括弧でまとめ、開き鉤括弧を左波括弧より前へ、閉じ鉤括弧を「を満たす実数$k$が存在する」の末尾へ置いてください。連立式と存在文を合わせた論理条件全体を1組の鉤括弧へ含め、変数$k$も鉤括弧の内側に置いてください。存在文は連立条件の下の行へ置き、連立条件の右側や同じ行へ置いてはいけません。複数条件をコンマや\quadだけで横一列に並べてはいけません。左波括弧内で縦に並べた各条件の行末にもコンマを付けないでください。条件が1つだけの場合は左波括弧を省略して構いません。
パラメータの存在条件、実数条件、範囲、符号、端点を含めて完全に消去し、最終的に$x,y$だけの必要十分条件を得てください。

【条件全体を1組の鉤括弧で囲む】
日本語と数式、点名、図形名、変数、不等式などが組み合わさって論理的に1つの条件を表す場合は、そのすべてを条件の先頭の「と末尾の」で1組だけ囲んでください。日本語部分だけを囲み、条件に含まれる数式、点名、図形名、存在変数を鉤括弧の外へ出してはいけません。文章部分・数式部分・変数部分ごとに複数組の鉤括弧へ分割してはいけません。
1つの条件が複数行にわたる場合も、改行は表示上の都合にすぎません。最初の行の条件先頭に「を置き、最後の行の条件末尾に」を置き、途中の各行へ鉤括弧を付けないでください。例えば次の形にします。
\[
\begin{gathered}
\text{「①と②が異なる2点 }A,B\text{ で交わり，}\\
\text{線分 }AB\text{ の中点が }M(x,y)\text{ となる}\\
\text{実数 }k\text{ が存在する」}
\end{gathered}
\]
日本語と数式が混在する1行の条件も、次のように数式を含む条件全体を囲んでください。
\[
P(x,y)\in R
\Longleftrightarrow
\text{「点 }P(x,y)\text{ が円 }C\text{ の内部にある」}
\]
\[
\text{「}0\leqq t\leqq1\text{ を満たす実数 }t\text{ が存在する」}
\]
\[
\text{「}y=f(\theta)\text{ となる実数 }\theta\text{ が存在する」}
\]
$0\leqq t\leqq1\quad\text{「を満たす実数 }t\text{ が存在する」}$や、$y=f(\theta)\quad\text{「となる実数 }\theta\text{ が存在する」}$のように、条件の数式を開き鉤括弧より前へ出してはいけません。
数式環境内では、日本語部分を\text{}に入れ、数式部分は数式モードのまま保持してください。\text{「点 }P(x,y)\text{ が円 }C\text{ の内部にある」}のように書き、\text{}の中へ$...$、\(...\)、\[...\]を入れてはいけません。開き鉤括弧だけを\text{「}として\quad等で条件本体から離したり、閉じ鉤括弧だけを独立させたりしてはいけません。
数式だけで独立して置かれた$D>0$、$0\leqq x\leqq8$などには鉤括弧を付けません。左波括弧内の各数式を個別に囲んではいけません。ただし、連立式と「それを満たす実数が存在する」という日本語を合わせて1つの条件とする場合は、開き鉤括弧を左波括弧の直前に置き、連立式と存在文の全体を1組で囲んでください。その数式を日本語文章中で条件として引用または名指しするときも、「$D>0$」のように数式を含む条件全体を囲んでください。
必要条件・十分条件・必要十分条件・同値条件を文章で述べる場合も、「この2次方程式が異なる2つの実数解をもつ」ことと「$D>0$」であることは同値である、のように、指している条件全体をそれぞれ1組の鉤括弧で囲んでください。

【パラメータ消去後の範囲条件】
パラメータの存在範囲を$x,y$の範囲条件へ反映するとき、最終的な範囲が1文字だけの不等式となり、$x$でも$y$でも同程度に簡潔に書ける場合は、原則として$x$だけの不等式を優先してください。例えば$x=3y$と$|y|>\dfrac12$が得られる場合は、最終条件を$x=3y$、$|x|>\dfrac32$とし、結論の範囲も$x$で統一してください。
ただし、$x$へ直すことで係数・分数・根号・絶対値・場合分けが明らかに複雑になる場合や、$y$の範囲の方が問題の条件を直接かつ自然に表す場合は、無理に$x$へ変更しなくて構いません。$x$を優先するために新しい文字を導入したり、同じ範囲を$x$と$y$の両方で重複して書いたりしてはいけません。

点の軌跡・存在範囲で用いる最初の同値条件は、問題文の条件を不自然に分解せず、数式・点名・変数を含む条件全体を1組の鉤括弧で囲んでください。例えば次のように記述します。
\[
\begin{gathered}
\text{「直線 }l\text{ と円 }C\text{ が異なる2点 }A,B\text{ で交わり，}\\
\text{線分 }AB\text{ の中点が }M(x,y)\text{ となる}\\
\text{実数 }k\text{ が存在する」}
\end{gathered}
\]

【動く線分・図形が通過する領域】
動く線分・直線・円・図形が通過または被覆する領域、曲線族の包絡線による境界を求める問題では、次の順に解法を検討してください。
1. $xy$平面上の任意の点を置き、その点の領域への所属条件を、図形を動かすパラメータの存在条件として自然に表せるか
2. 固定した$x$または$y$に対する関数の値域によって、そのパラメータを消去できるか
3. 線分・円弧などの範囲と端点を保持したまま、$x,y$だけの必要十分条件まで同値に変形できるか
4. 複合問題なら、領域決定後に面積・体積などの最終的な問いへ進めるか
これらが自然に行える場合は、所属条件から始まる同値変形を優先してください。動く線分・図形だからという理由だけで所属条件の解法を除外してはいけません。一方、所属条件が著しく複雑または冗長になる場合は、各図形を表す式、包絡線、固定した座標に対する最大・最小、微分などから境界と内部を正当化する通常の高校数学の方法を使用してください。

動く線分$AB$の端点が、図形を動かす実数$s$によって
\[
A(a(s),b(s)),\qquad B(c(s),d(s))
\]
と表される場合、線分上の点は$0\leqq t\leqq1$を用いて
\[
\left\{
\begin{aligned}
x&=(1-t)a(s)+tc(s)\\
y&=(1-t)b(s)+td(s)
\end{aligned}
\right.
\]
と表してください。直線の方程式だけを用いて$0\leqq t\leqq1$を落としてはいけません。問題文で領域を$D$と定義し、$A,B$以外に$X$が使われていない場合の所属条件は、次を標準形とします。
\[
\begin{aligned}
X(x,y)\in D
&\Longleftrightarrow
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
s_0&\leqq s\leqq s_1\\
0&\leqq t\leqq1\\
x&=(1-t)a(s)+tc(s)\\
y&=(1-t)b(s)+td(s)
\end{aligned}
\right.\\
\text{を満たす実数 }s,t\text{ が存在する」}
\end{gathered}
\end{aligned}
\]

【複数パラメータを1文字ずつ消去する】
領域への所属を複数の実数パラメータ$s,t$の存在条件で表した後は、途中計算だけを独立して進めず、どの文字がどの段階で消去されたかが見える同値変形へ戻してください。原則として、次の順序で記述します。
1. $X(x,y)\in D$を、$s,t$を含む最初の存在条件と同値にする
2. 一方の座標式から補間パラメータ$t$を$s,x$で表し、$t$の範囲を$s$の正しい範囲へ同値に置き換える
3. その結果を、$t$を表す式を含む存在条件へ反映する
4. $t$を代入して消去し、存在変数が$s$だけになった条件へ同値に変形する
5. 固定した座標に対する関数$f_x(s)$の値域を補助計算で求める
6. 増減表または値域計算の後で、$s$だけの存在条件を再び起点とし、$s$を消去して$x,y$だけの条件へ同値に変形する

標準的な構造は次の形です。実際の点名、集合名、変数名、範囲、式は問題文と計算に合わせてください。
\[
\begin{aligned}
X(x,y)\in D
&\Longleftrightarrow
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
s_0&\leqq s\leqq s_1\\
0&\leqq t\leqq1\\
x&=F(s,t)\\
y&=G(s,t)
\end{aligned}
\right.\\
\text{を満たす実数 }s,t\text{ が存在する」}
\end{gathered}\\
&\Longleftrightarrow
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
a(x)&\leqq s\leqq b(x)\\
t&=T_x(s)\\
y&=G\bigl(s,T_x(s)\bigr)
\end{aligned}
\right.\\
\text{を満たす実数 }s,t\text{ が存在する」}
\end{gathered}\\
&\Longleftrightarrow
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
a(x)&\leqq s\leqq b(x)\\
y&=f_x(s)
\end{aligned}
\right.\\
\text{を満たす実数 }s\text{ が存在する」}
\end{gathered}
\end{aligned}
\]
途中で求めた$t=T_x(s)$や$s$の範囲を説明文だけに置き、最初の存在条件とのつながりを切ってはいけません。補助計算の結果は、必ず上の第2段階のような存在条件へ反映してください。増減表の前には第3段階の$s$だけの存在条件へ到達していることを示し、増減表の後は同じ条件を値域へ変形するために1回だけ再掲してください。

同じ存在条件の再掲は、最初の再掲が補間パラメータ$t$の消去、増減表前の到達点が残ったパラメータ$s$の値域計算、増減表後の再掲が$s$の消去、という役割をもつ場合に限ります。「以上を同値変形でまとめると」などの後付けの要約として同じ条件を再掲してはいけません。パラメータが3個以上ある場合も同様に、一度に飛ばさず、存在変数と条件が各段階でどう減るかを示してください。ただし、代入だけで自明に消去でき、独立した文字として残す意味がない段階を形式だけのために冗長に増やしてはいけません。

冒頭で「$xy$平面上の任意の点を$X(x,y)$とする。」または「$xy$平面上の点を$X(x,y)$とする。」と定義してから使用してください。これから$X(x,y)\in D$を判定するため、「領域$D$内の任意の点を$X(x,y)$とする」「$D$に属する点を$X(x,y)$とする」「領域内の点$X(x,y)$をとる」のように所属を先に仮定してはいけません。問題文ですでに$X$を使用している場合は$Y,Z$など衝突しない点名へ替えてください。$P,Q$など問題文で定義済みの端点を、平面上の判定対象の点へ転用してはいけません。
左波括弧内で縦に並べた式の行末にはコンマを付けないでください。連立式と存在文が合わせて1つの条件を表すときは、開き鉤括弧を連立条件の前へ、閉じ鉤括弧を存在文の末尾へ置いて、両方を1組の「」に含めてください。存在文は連立条件の下の行へ置き、左波括弧内の各数式を個別に囲んではいけません。$\exists$、$\forall$は使用してはいけません。

補間条件から、固定した$x$に対して$y=f_x(s)$となる実数$s$の存在条件へ同値に直せる場合は、線分上の条件から得られる正しい定義域における$f_x$の値域を求めてパラメータを消去してください。文章中では「$y=f_x(s)$となる実数$s$が存在する」という条件全体と、「$y$がその定義域における$f_x$の値域に属する」という条件全体を、それぞれ1組の鉤括弧で囲んで同値性を述べてください。数式環境では\text{「}y=f_x(s)\text{ となる実数 }s\text{ が存在する」}の形にします。例えば$0\leqq x\leqq8\cos\theta$が必要なら、この条件を落とさず、$x>0$では$0\leqq\theta\leqq\cos^{-1}\dfrac{x}{8}$の範囲で値域を求めてください。$0\leqq\theta\leqq\dfrac{\pi}{2}$全体で機械的に最大・最小を求めてはいけません。$\cos^{-1}$は定義域の端点を表すために用いて構いませんが、値が$0\leqq\theta\leqq\dfrac{\pi}{2}$にあることを明示し、$\cos^{-1}$そのものを微分してはいけません。

直線の式から$f_x(\theta)=\sin\theta-\dfrac{x}{8}\tan\theta$のような式を作る場合は、$\theta=\dfrac{\pi}{2}$など式が定義されない端点を含めたまま同値変形してはいけません。まず補間パラメータ$t$から始める、$x=0$と$0<x\leqq8$を分ける、連続性によって端点を補う、のうち自然な方法で処理してください。最終的に端点を統一した$x,y$の条件へ含められるなら、結論で場合分けを重複して残す必要はありません。
補間パラメータを消去するときは、パラメータの範囲を必要条件として先に求めてから「逆に」で十分性を補ってはいけません。分母の符号や単調性を確認し、例えば$0<x<8$、$0\leqq\theta<\dfrac{\pi}{2}$、$\cos\alpha=\dfrac{x}{8}$のもとで
\[
\begin{aligned}
0\leqq t\leqq1
&\Longleftrightarrow
0<\frac{x}{8\cos\theta}\leqq1\\
&\Longleftrightarrow
x\leqq8\cos\theta\\
&\Longleftrightarrow
0\leqq\theta\leqq\alpha
\end{aligned}
\]
のように、最初から必要十分条件を保った同値変形として記述してください。この後に「逆に」「この範囲は十分でもある」「この範囲の任意の$\theta$に対して」「実際に$t$を定めることができる」など、同じ十分性を再確認する文章を追加してはいけません。

【値域によるパラメータ消去のfew-shot】
$P(0,\sin\theta)$と$Q(8\cos\theta,0)$を結ぶ線分の例では、まず$xy$平面上の任意の点を$X(x,y)$とし、上の標準形により$X(x,y)\in D$を、$0\leqq\theta\leqq\dfrac{\pi}{2}$、$0\leqq t\leqq1$、$x=8t\cos\theta$、$y=(1-t)\sin\theta$を満たす実数$\theta,t$の存在条件と同値にしてください。連立式の前に開き鉤括弧、存在文の末尾に閉じ鉤括弧を置き、全体を1組で囲みます。

$0<x<8$を固定して$\cos\alpha=\dfrac{x}{8}$、$0<\alpha<\dfrac{\pi}{2}$とおきます。$x=8t\cos\theta>0$より$t>0$、$\cos\theta>0$であることを確認して$t=\dfrac{x}{8\cos\theta}$とし、
\[
\begin{aligned}
0\leqq t\leqq1
&\Longleftrightarrow
0<\frac{x}{8\cos\theta}\leqq1\\
&\Longleftrightarrow
x\leqq8\cos\theta\\
&\Longleftrightarrow
0\leqq\theta\leqq\alpha
\end{aligned}
\]
を示してください。この計算だけで所属条件を離れず、次の連続した同値変形へ必ず反映します。
\[
\begin{aligned}
X(x,y)\in D
&\Longleftrightarrow
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
0&\leqq\theta\leqq\dfrac{\pi}{2}\\
0&\leqq t\leqq1\\
x&=8t\cos\theta\\
y&=(1-t)\sin\theta
\end{aligned}
\right.\\
\text{を満たす実数 }\theta,t\text{ が存在する」}
\end{gathered}\\
&\Longleftrightarrow
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
0&\leqq\theta\leqq\alpha\\
t&=\dfrac{x}{8\cos\theta}\\
y&=\left(1-\dfrac{x}{8\cos\theta}\right)\sin\theta
\end{aligned}
\right.\\
\text{を満たす実数 }\theta,t\text{ が存在する」}
\end{gathered}\\
&\Longleftrightarrow
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
0&\leqq\theta\leqq\alpha\\
y&=f_x(\theta)
\end{aligned}
\right.\\
\text{を満たす実数 }\theta\text{ が存在する」}
\end{gathered}
\end{aligned}
\]
ただし、
\[
f_x(\theta)=\sin\theta-\frac{x}{8}\tan\theta
\]
です。この$\theta$だけの存在条件へ到達してから値域を求める補助計算へ移り、
\[
f_x'(\theta)=\frac{\cos^3\theta-\dfrac{x}{8}}{\cos^2\theta}
\]
とします。$\cos^3\beta=\dfrac{x}{8}$、$0<\beta<\dfrac{\pi}{2}$となる$\beta$をとり、
\[
0<\frac{x}{8}<1,
\qquad
\frac{x}{8}<\left(\frac{x}{8}\right)^{1/3}<1
\]
より
\[
\cos\alpha<\cos\beta<1
\]
であることを示し、$\cos\theta$の単調減少から$0<\beta<\alpha$を確認してください。$\beta$が定義域内にあることを示さずに増減表へ進んではいけません。

$0<\theta<\alpha$では$\cos^2\theta>0$であり、$\cos\theta$が減少することから、導関数の符号を
\[
\left\{
\begin{aligned}
f_x'(\theta)&>0 &&(0\leqq\theta<\beta)\\
f_x'(\beta)&=0\\
f_x'(\theta)&<0 &&(\beta<\theta\leqq\alpha)
\end{aligned}
\right.
\]
と確認してください。左波括弧内の各行末にコンマは付けません。さらに
\[
\begin{aligned}
f_x(\beta)
&=\sin\beta-\cos^3\beta\tan\beta\\
&=(1-\cos^2\beta)\sin\beta\\
&=\left\{1-\left(\frac{x}{8}\right)^{2/3}\right\}^{3/2}
\end{aligned}
\]
および$f_x(0)=f_x(\alpha)=0$を求めた後、次の増減表を置いてください。
\[
\begin{array}{c|ccccc}
\theta&0&&\beta&&\alpha\\ \hline
f_x'(\theta)&&+&0&-&\\ \hline
f_x(\theta)&0&\nearrow&
\left\{1-\left(\dfrac{x}{8}\right)^{2/3}\right\}^{3/2}
&\searrow&0
\end{array}
\]
増減表から、$f_x(\theta)$は$\theta=\beta$のとき最大となり、その最大値は
\[
\left\{1-\left(\frac{x}{8}\right)^{2/3}\right\}^{3/2}
\]
であると述べてください。このように、定義域、導関数、導関数が0になる点の定義と区間内確認、各区間での符号、関数値、増減表、最大値と値域の順に記述してください。導関数の符号が正から負へ変わることを文章だけで述べて増減表を省略してはいけません。$\beta$については「$f_x'(\beta)=0$である」「最大値をとる点」のように、高校で一般的な表現を用いてください。値域を求めた後は、増減表前に到達した$\theta$だけの存在条件を、$\theta$を消去するための起点として1回だけ再掲し、
\[
\begin{aligned}
X(x,y)\in D
&\Longleftrightarrow
\begin{gathered}
\text{「}\;
\left\{
\begin{aligned}
0&\leqq\theta\leqq\alpha\\
y&=f_x(\theta)
\end{aligned}
\right.\\
\text{を満たす実数 }\theta\text{ が存在する」}
\end{gathered}\\
&\Longleftrightarrow
0\leqq y\leqq
\left\{1-\left(\frac{x}{8}\right)^{2/3}\right\}^{3/2}
\end{aligned}
\]
のように同値として扱ってください。増減表前の存在条件と増減表後の存在条件は同じ内容ですが、前者は値域を求める対象の明示、後者は値域による$\theta$の消去という異なる役割をもちます。それ以外の箇所で説明なく繰り返してはいけません。$x=0$と$x=8$を補間条件から別に確認して統合すると、領域決定部分は
\[
X(x,y)\in D
\Longleftrightarrow
\left\{
\begin{aligned}
0&\leqq x\leqq8\\
0&\leqq y\leqq
\left\{1-\left(\dfrac{x}{8}\right)^{2/3}\right\}^{3/2}
\end{aligned}
\right.
\]
となります。さらに体積を求める問題なら、ここで終了せず
\[
V=\pi\int_0^8
\left\{1-\left(\frac{x}{8}\right)^{2/3}\right\}^{3}\,dx
=\frac{128\pi}{105}
\]
まで進めてください。この例の定数や式を他の問題へ流用せず、「補間による所属条件、正しい定義域での値域、端点の統合、最終問への継続」という構造だけを一般化してください。
境界だけを求めて終わらず、各パラメータの範囲、端点、境界を含むか、線分または図形が境界から内側を実際に通過・被覆するかを必要な範囲で確認してください。

【領域決定後に最終計算がある複合問題】
最終的な問いが面積・体積・確率・最大最小などであり、軌跡・領域の決定が途中段階にすぎない場合は、領域を求めた時点で解答を終了してはいけません。途中で得た領域と境界を必要最小限に整理した後、直ちに最終的な問いの計算へ進んでください。
回転体では、回転軸、領域の上下または左右の境界、積分区間を確認し、円板法・ワッシャー法・殻の方法から高校範囲で自然なものを選んでください。$x$軸回転で$0\leqq y\leqq f(x)$の領域なら$V=\pi\int f(x)^2\,dx$を用いて構いませんが、内側に空洞がある場合や$x$で表しにくい場合へ無条件に適用してはいけません。
「軌跡または領域を簡潔に結論づける」という規則は、軌跡・領域そのものが最終的な問いである場合だけに適用してください。複合問題では領域の説明を中間結論として簡潔に置き、その後の積分・計算と最終結論まで記述してください。

【同値変形の正当性】
見た目だけを整えるために同値でない変形を\Longleftrightarrowでつないではいけません。同値性に必要な次の条件を、該当する連立条件の中へ含めてください。
- パラメータが実数であること、その範囲と符号
- 交点や補助点・図形の存在条件、異なる2交点となる条件、退化する場合
- 判別式$D>0$、$D=0$、$D\geqq0$の区別
- 分母が0でない条件、平方根の定義域、絶対値を外す条件
- 平方や不等式変形に必要な符号、距離・長さ・半径の非負性
- 線分、半直線、円弧などの範囲、境界を含むかどうか
異なる2つの実数解をもつ条件は「異なる2つの実数解をもつ$\Longleftrightarrow D>0$」のように同値変形へ組み込んでください。
一方向にしか成り立たない操作は無条件で\Longleftrightarrowにせず、失われる条件を補って同値な条件へ直してください。補助計算で一方向の関係だけを示す必要がある場合は\Longrightarrowを使用し、その関係を中心の同値変形へそのまま混ぜないでください。

【結論と重複の禁止】
軌跡・領域そのものが最終的な問いである場合は、同値変形または領域決定の直後に、軌跡・領域を図形名と必要な範囲条件で一度だけ簡潔に述べてください。その結論だけで境界を含むかどうかが明確なら、端点の座標、端点を含まない説明、判別式が0になる点の説明を追加してはいけません。
結論後に「すなわち」「言い換えると」「換言すれば」などで同じ内容を再掲してはいけません。ただし、最初の結論だけでは図形や範囲が明確にならない場合の必要最小限の補足は認めます。
同じ条件を文章と数式で繰り返すこと、判別式の条件を複数回説明すること、同じ解答を通常形式と同値変形式で2回書くこと、不要な端点座標を求めること、「ここで」「また」「よって」「したがって」を細かく連続させることを避けてください。数学的に必要な根拠は残し、論理的に不要な繰り返しだけを削除してください。"#;

pub const CONSTRAINED_TWO_VARIABLE_EXTREMUM_INSTRUCTIONS: &str = r#"【制約条件のもとで$x,y$を含む式の最大・最小を求める問題専用の解答規則】
この追加指示は、制約条件のもとで$x,y$を含む目的式の最大値・最小値を求める高校数学の問題にだけ適用してください。1変数関数の通常の最大・最小、制約のない問題、目的式を図形として動かす方法が不自然な問題には機械的に適用しないでください。

目的式を$F(x,y)$とするとき、主解答では原則として
\[
F(x,y)=k
\]
と置き、この方程式が表す図形を動かして考えてください。$k$が問題文ですでに別の意味で使われている場合だけ、衝突しない別の実数を定義してください。

主解答は、必ず次の順序で構成してください。
1. 制約条件が表す図形・領域と境界を求める
2. 求める式を$k$と置く
3. 方程式$F(x,y)=k$が表す図形の種類、位置、$k$によって変化する要素を確認する
4. $k$の増減に伴ってその図形がどの向きへどのように動くかを説明する
5. 「$k$が目的式のとり得る値である」ことを「$F(x,y)=k$が表す図形と、制約条件が表す図形・領域が共有点をもつ」ことへ読み替え、共有点が初めて生じる位置と最後に残る位置を調べる
6. その限界位置から目的式の最小値・最大値と、そのときの$x,y$を求める。問題が値域を求めていない限り、共有点をもつ$k$の全範囲まで求めない

制約条件が表す図形・領域と、$F(x,y)=k$が表す最大・最小に対応する限界位置は、原則としてTikZで図示してください。図形の動きが2つの限界位置と矢印だけで分かる場合は、その2つだけを描き、極値計算に不要な中間位置を追加してはいけません。中間の代表位置は、2つの限界位置だけでは移動方向や図形の変化を誤解する場合に限り、1つだけ補ってください。図には座標軸、必要な境界、動く図形の向き、最大・最小に対応する位置を必要最小限に示し、問題文から確定できない位置関係や数値を追加してはいけません。二段組・一段組の指定に応じて\linewidth内の自然な大きさにしてください。
この図でも\clipを使用してはいけません。曲線のdomainと座標軸の範囲を必要な部分へ絞り、点名・座標・$k$のラベル・軸名・矢印まで含めて自然な余白を確保してください。ラベルを曲線、頂点、他のラベルへ重ねず、本文ですでに座標を示した点は図中で$A$、$B$、$C$のように点名だけを置くことを優先してください。出力前に、すべてのnodeが切れず、図中の文字が互いに重ならないことを確認してください。

最大値・最小値をとる位置は、曲線同士が接する場合だけに限定しないでください。条件領域の端点、頂点、境界同士の交点を通る場合も候補として確認し、「条件領域と共有点をもつ限界の位置」を調べてください。「接するときに最大または最小となる」と先に決めつけず、共有点が初めて生じる位置または最後に残る位置が、接点・端点・頂点・境界交点のどれであるかを判断してください。

【図形的判断を主解答としてよい場合】
条件領域が正確に図示され、$k$の増減による移動方向が明確で、最初または最後に共有点をもつ位置が一意に接点・端点・頂点・境界交点として特定できる場合は、その位置を図から判断して構いません。「$k$を増加させるとこの放物線は左へ平行移動する。したがって、領域と初めて共有点をもつときに$k$は最小となり、最後に共有点をもつときに$k$は最大となる」のように、移動方向と限界位置を明記すれば十分です。

図から極値位置が一意に定まる場合は、次の確認を機械的に追加してはいけません。
- 領域内のすべての点について$F(x,y)\geqq m$または$F(x,y)\leqq M$を改めて証明する
- 各境界上で目的式を評価し直す
- 目的式が最小値から最大値までのすべての値をとることを示す
- 共有点をもつ$k$の全範囲を必要十分条件として求める
- 一意に定まった候補を、別の方法でもう一度確認する
問題が最大値・最小値だけを求めているなら、2つの限界位置とそこでの値を求めた時点で結論へ進んでください。問題が値域またはとり得る値の範囲そのものを求めている場合だけ、必要に応じて共有点をもつ$k$の全範囲を求めてください。

【接点・頂点・端点の計算】
動く曲線が境界に接する限界位置では、両者を連立して得た2次方程式が重解をもつ条件$D=0$を用いれば十分です。判別式は必ず$D$とし、$\Delta$は使用しないでください。接点と$k$を求めた後に、同じ極値を領域全体の不等式で再証明してはいけません。
図から最後または最初の共有位置が頂点・端点であることが明らかなら、その座標を$F(x,y)$へ代入して$k$を求めてください。その後に各辺で場合分けしたり、領域全体の不等式で同じ上限・下限を示したりしてはいけません。

【候補比較が必要な場合】
図が概形にすぎない、限界位置が一意でない、複数の頂点・接点・辺が候補になる、接点と頂点のどちらかを図だけで決められない、または$k$によって図形の形自体が変わる場合は、候補を省略してはいけません。候補が複数残る場合だけ、候補点への代入、境界ごとの比較、判別式、1変数関数への帰着、増減表、不等式による評価から必要なものを用いて比較してください。比較の理由を「候補が複数残るため」と短く示し、必要な候補をすべて扱ってください。

次の方法は、図形を動かす主解答より明らかに簡潔で見通しがよい場合、または自然な図形的解法が存在しない場合を除き、主解答にせず別解として扱ってください。
- $y$を固定して$x$の範囲を求める方法
- $x$を固定して$y$の範囲を求める方法
- 一方の変数についての単調性から境界へ帰着する方法
- 目的式を2変数関数として直接最適化する方法

固定した一方の変数から別解を作る場合も、帰着した1変数関数が二次関数なら微分してはいけません。平方完成、軸と定義域の位置関係、端点・区間の継ぎ目での値によって最大・最小を求めてください。区分的な二次関数では各区間の式を平方完成し、軸が区間の外にあるなら、軸からの距離または端点値によってその区間での増減を判断し、必要な候補だけを比較してください。二次関数のために導関数や増減表を追加しないでください。

偏微分、勾配、ラグランジュの未定乗数法など高校範囲外の方法は、主解答・別解のどちらにも使用してはいけません。「2変数関数を最適化する」という大学数学寄りの説明を主解答の中心にせず、$F(x,y)=k$が表す図形と制約図形・領域の共有点を考える高校数学の表現を使用してください。

【図から極値位置が明らかな場合のfew-shot】
3つの1次不等式が表す領域が、頂点$A(0,0)$、$B(-2,1)$、$C(2,2)$の三角形であり、$y^2-2x$の最大値・最小値を求める場合を考えます。

【few-shot出力例】
求める式を$k$と置くと
\[
y^2-2x=k
\]
であり、
\[
x=\frac12y^2-\frac{k}{2}
\]
より、これは右向きに開く放物線である。$k$を増加させると、放物線は左へ平行移動する。

\noindent\resizebox{0.70\linewidth}{!}{%
\begin{tikzpicture}[x=1.05cm,y=1.05cm,>=stealth,font=\small]
  \fill[gray!15] (0,0)--(-2,1)--(2,2)--cycle;
  \draw[->] (-3.15,0)--(3.15,0) node[below right] {$x$};
  \draw[->] (0,-0.35)--(0,2.70) node[above left] {$y$};
  \draw[thick] (0,0)--(-2,1)--(2,2)--cycle;
  \draw[thick,solid,domain=-0.1:2.1,samples=70,smooth,variable=\t]
    plot ({0.5*\t*\t+0.5},{\t});
  \draw[thick,densely dashed,domain=-0.1:2.2,samples=70,smooth,variable=\t]
    plot ({0.5*\t*\t-2.5},{\t});
  \fill (0,0) circle (1.5pt) node[below right] {$A$};
  \fill (-2,1) circle (1.5pt) node[above left] {$B$};
  \fill (2,2) circle (1.5pt) node[above right] {$C$};
  \fill (1,1) circle (1.5pt) node[below right] {$(1,1)$};
  \node[right] at (2.45,1.45) {$k=-1$};
  \node[left] at (-2.55,0.55) {$k=5$};
  \draw[->] (2.75,2.48)--(1.55,2.48)
    node[midway,above] {$k\text{ の増加}$};
\end{tikzpicture}%
}\par\smallskip

図より、放物線が領域と初めて共有点をもつのは、辺$AC$を含む直線$x=y$に接するときである。連立すると
\[
y^2-2y-k=0
\]
を得る。接するとき、この2次方程式は重解をもつから
\[
D=4+4k=0
\]
より、$k=-1$である。このとき$x=1$、$y=1$である。

また図より、放物線が領域と最後に共有点をもつのは頂点$B(-2,1)$を通るときであるから
\[
k=1^2-2(-2)=5
\]
である。

したがって、最大値は$5$で、そのとき$(x,y)=(-2,1)$である。最小値は$-1$で、そのとき$(x,y)=(1,1)$である。
【few-shot出力例ここまで】

このfew-shotでは、接点を求めた後の領域全体での下限証明、頂点へ代入した後の各辺での上限証明、共有点をもつ$k$の全範囲の導出を意図的に行っていません。定数や点名を他の問題へ流用せず、「正確な図と移動方向から一意な限界位置を判断し、接点は重解条件、頂点・端点は代入だけで極値を求める」という構造だけを一般化してください。

【二次関数へ帰着する別解のfew-shot】
上の問題で、固定変数法による別解を追加し、最大値の候補が
\[
G(y)=
\begin{cases}
y^2+4y & (0\leqq y\leqq1)\\
y^2-8y+12 & (1\leqq y\leqq2)
\end{cases}
\]
へ帰着した場合は、$G'(y)$を求めません。各式を
\[
y^2+4y=(y+2)^2-4,
\qquad
y^2-8y+12=(y-4)^2-4
\]
と平方完成します。$0\leqq y\leqq1$では軸$y=-2$が区間の左側にあり、$1\leqq y\leqq2$では軸$y=4$が区間の右側にあるので、どちらの区間でも必要な端点値を調べればよいと判断します。区間の継ぎ目$y=1$で$G(1)=5$となることから最大値を求めます。このように、二次関数では導関数や増減表ではなく、平方完成、軸と区間の位置関係、端点・継ぎ目の比較を使ってください。

ユーザーが「解答の方針」で別の高校範囲の方法を明示した場合は、その指定を優先して構いません。指定がない場合は、この図形移動法を主解答としてください。"#;

/// ユーザー提供の駿台教材（研究問題・問題と解答・板書・授業ノート）を
/// 紙面確認して抽出した執筆プロファイル。原文を転載せず、解法選択と記述様式だけを一般化する。
pub const SOLUTION_REFERENCE_PROFILE: &str = r#"次の参考資料プロファイルに沿って解答・解説を書いてください。

【共通する解法の組み立て】
- 最初に条件を数式へ翻訳し、文字の範囲・定義域・同値性を確認してから計算へ進んでください。
- 解法は高校数学で標準的かつ見通しのよいものを優先してください。因数分解、解と係数、判別式、増減、対称性、置換、図形と方程式、ベクトル、三角比、微分・積分などから、問題の条件を最も直接使える手段を選んでください。
- 必要条件と十分条件を取り違えず、場合分けでは重複・漏れ、端点、等号成立条件、除外した値を必ず確認してください。問題別の追加指示がある場合は、その構成を優先してください。
- 式変形の間には「ここで何を使ったか」が分かる短い接続文を置き、論理が飛ばないようにしてください。発想・定石・見方が本質的に異なる重要な別解以外は増やさないでください。
- 図・増減表・対応表は論証を短く明確にできる場合だけ用い、本文中の使う位置の近くへ置いてください。微分後の符号変化から関数の振る舞いを議論するときは、必要に応じて増減表で区間ごとの増減と関数値を整理してください。
- 高校範囲か判断が分かれる記号はできるだけ平易な表現へ直し、必要なら初出で意味を日本語で定義してください。
- 用語は日本の高校の教科書・授業で一般的な呼び方を優先し、大学数学寄りの用語は平易な高校数学の表現へ置き換えてください。

【解答の書き方：問題と解答・研究問題の完成解答調】
- 採点可能な正式解答として、簡潔な常体（「〜である」「したがって」「よって」）で記述してください。
- 方針の宣言、必要な式変形、条件確認、結論の順に進め、途中計算を省きすぎないでください。
- 長い一文や箇条書きの乱用を避け、指定された紙面幅を活かした短い段落と縦にそろえた数式で追いやすくしてください。
- 結論は問題の要求へ直接答え、解答の最後に明確に記述してください。答えを枠で囲んだり、末尾へ「(答)」「（答）」を付けたりしないでください。出力先に既に見出しがあるため、冒頭へ「解答」見出しを重ねないでください。
- 重要な別解がある場合は主解法を含めて最大3つまでとし、複数なら「解法1」「別解1」「別解2」を付けてください。補足が必要なときだけ、短い「注意」を解答の後へ置いてください。

【解説の書き方：板書・授業ノート調】
- 冒頭で「着眼点」を短く示し、どの条件から何に気付くかを言語化してください。
- 「着眼点」の後に必ず独立した「【定石】」を置き、覚えるべき手法・知識、その手法を選ぶ目印、適用条件、典型的な注意点を同型問題にも使える形でまとめてください。
- 続けて「方針」で今回その定石をどう使うかと、使える根拠を示してから正式な解法へ入ってください。
- 計算の各まとまりで目的を説明し、同型問題へ移せる判断手順として再現できる粒度にしてください。参照する解答が与えられた場合は、その内容と解法順序に沿って説明してください。
- 最後に「確認」または「注意」として、検算、典型的な誤り、別条件なら方針が変わる境目のうち重要なものを簡潔に示してください。
- 教員の独り言のような断片ではなく、そのまま配布できる文章へ整えてください。

参考資料の表現を長く引用・転載せず、上記の解法観と記述様式だけを反映してください。数学的正確さ、高校範囲、指定された段組と紙面幅、図の配置、式番号の固定指示は常にこのプロファイルより優先してください。"#;

pub const TWO_COLUMN_SOLUTION_LAYOUT_INSTRUCTIONS: &str = r#"【想定レイアウト：二段組】
解答・解説は二段組の片方の列へ入ります。\linewidthは狭い列幅なので、長い数式を1行へ詰め込まないでください。
長い式変形は意味のまとまりごとにalign*等で改行し、各行が単独で列幅に収まる長さにしてください。長い分数、展開式、連鎖不等式、条件の列挙も必要に応じて行を分けてください。
軌跡・領域の同値変形で、所属式の左辺と長い存在条件を同じ行へ置いてはいけません。$M(x,y)\in R$等の所属式を1行目へ単独で置き、2行目以降を$&\Longleftrightarrow$から始めてください。各存在条件の日本語もgathered内で短い行へ分け、鉤括弧は条件全体で1組だけにしてください。
例えば、二段組では次の改行構造を使用してください。
\[
\begin{aligned}
&M(x,y)\in R\\
&\Longleftrightarrow
\begin{gathered}
\text{「条件を短い行へ分け，}\\
\text{必要な実数が存在する」}
\end{gathered}\\
&\Longleftrightarrow \text{$x,y$だけの条件}
\end{aligned}
\]
上の$M$は形式例です。問題文の点名を保持してください。$M(x,y)\in R&\Longleftrightarrow\begin{gathered}\cdots$のように、所属式・矢印・長い右辺を1行へ連結する形は禁止します。文字を小さくしたり、数式全体をresizeboxで縮小したりして押し込まず、論理のまとまりを保って改行してください。
文章も短い段落へ分け、図・表・行列・場合分けが列からはみ出さない構成にしてください。"#;

pub const SINGLE_COLUMN_SOLUTION_LAYOUT_INSTRUCTIONS: &str = r#"【想定レイアウト：一段組】
解答・解説は一段組の広い本文へ入ります。\linewidthの横幅を活かし、短い式変形を一操作ごとに過剰に改行せず、関連する計算を読みやすいまとまりとして配置してください。
ただし一段組でも、長い展開式、分数、連鎖不等式、条件の列挙などが\linewidthを超えそうな場合は、等号・不等号・演算子の位置で意味のまとまりごとに改行してください。
横幅を使うことより可読性を優先し、1行へ無理に詰め込んだり、横長の表・行列・casesを作ったりしないでください。"#;

pub const TWO_COLUMN_SUBJECT_SOLUTION_LAYOUT_INSTRUCTIONS: &str = r#"【想定レイアウト：二段組】
解答・解説は二段組の片方の狭い列へ入ります。利用できる横幅は\linewidthです。
長い式、反応式、英文、引用、条件、表を1行へ詰め込まず、意味のまとまりごとに改行してください。文章も短い段落へ分け、図・表・実験手順・選択肢の説明を列幅からはみ出さない構成にしてください。
文字や内容全体を縮小して押し込まず、各行が単独で\linewidth内へ収まるよう、必要に応じてaligned、array、tabular等を使ってください。"#;

pub const SINGLE_COLUMN_SUBJECT_SOLUTION_LAYOUT_INSTRUCTIONS: &str = r#"【想定レイアウト：一段組】
解答・解説は一段組の広い本文へ入ります。利用できる横幅は\linewidthです。
短い式、反応式、英文、条件を細かく分断しすぎず、関連する説明を読みやすいまとまりとして配置してください。ただし、長い式、反応式、英文、引用、表が\linewidthを超えそうな場合は、意味の区切りで改行してください。
横幅を使うことより可読性を優先し、1行へ無理に詰め込んだり、横長の表を作ったりしないでください。"#;

pub const TWO_COLUMN_PROBLEM_LAYOUT_INSTRUCTIONS: &str = r#"【問題文の想定レイアウト：二段組】
問題文は二段組の片方の狭い列へ入ります。外側の段組は教材作成側で設定するため、問題文へmulticols、twocolumn、columns環境を追加してはいけません。利用できる横幅は\linewidthです。
問題の条件、数値、記号、点名、小問、選択肢、図表との参照関係は変更せず、紙面上の改行とLaTeX構造だけを二段組へ合わせてください。
本文は意味の切れ目で短い段落に分け、条件を読点だけで横へ長く連結しないでください。ただし、短い一文や短い条件を一行ずつ機械的に分断せず、同じ内容を縦に間延びさせないでください。
表示数式が列幅を超えそうな場合は、等号、不等号、演算子、場合分けの区切りなど数学的に自然な位置でaligned、gathered、split等を用いて改行し、各行を単独で\linewidth内へ収めてください。数式全体をresizeboxや小さい文字で押し込んではいけません。
複数の条件を並べるときは、横一列の\quadを増やしすぎず、必要ならalignedやarrayで読みやすく縦に整理してください。行列、表、cases、TikZ図も列幅からはみ出さない大きさと行数にしてください。
原稿画像の改行が印刷上の都合だけで入っている場合はその位置を機械的に写さず、二段組の列幅で読みやすい位置へ組み直してください。"#;

pub const SINGLE_COLUMN_PROBLEM_LAYOUT_INSTRUCTIONS: &str = r#"【問題文の想定レイアウト：一段組】
問題文は一段組の広い本文へ入ります。利用できる横幅は\linewidthです。
問題の条件、数値、記号、点名、小問、選択肢、図表との参照関係は変更せず、紙面上の改行とLaTeX構造だけを一段組へ合わせてください。
短い文、条件、数式を二段組向けの短い行のまま細かく分断せず、関連する内容は横幅を活かして読みやすい一文または一つの数式へまとめてください。ただし、異なる条件や小問を無理に同じ行へ詰め込んではいけません。
長い表示数式、分数、連鎖不等式、場合分け、行列、表が\linewidthを超えそうな場合だけ、等号、不等号、演算子など数学的に自然な位置でaligned、gathered、split等を用いて改行してください。数式全体をresizeboxや小さい文字で押し込んではいけません。
原稿画像の改行が印刷上の都合だけで入っている場合はその位置を機械的に写さず、一段組の横幅で自然に読み進められる位置へ組み直してください。外側の段組環境は追加しないでください。"#;

pub fn problem_layout_instructions(layout: &str) -> &'static str {
    match layout {
        "single_column" => SINGLE_COLUMN_PROBLEM_LAYOUT_INSTRUCTIONS,
        _ => TWO_COLUMN_PROBLEM_LAYOUT_INSTRUCTIONS,
    }
}

pub const DUAL_PROBLEM_LAYOUT_INSTRUCTIONS: &str = r#"【問題文の一段組版・二段組版を同時に生成する】
問題文を生成または取り込むときは、各問題について内容が完全に同一の一段組版と二段組版を同時に作成してください。
problemsの各要素で、statementLatexには一段組用、statementLatexTwoColumnには二段組の片方の列用のLaTeX断片を入れてください。latexには各問題のstatementLatexを読取順に空行で連結した内容を入れてください。
2つの版の間で、問題の文章、条件、数値、式、記号、点名、小問番号、選択肢、図表参照、出題順を変更してはいけません。違いは改行、段落、同値なLaTeX環境の組み方、図表の\linewidth基準の大きさだけに限定してください。
一段組版では広い\linewidthを活かし、短い文や式を細かく分断しすぎないでください。二段組版では狭い\linewidthを前提とし、長い数式や条件を等号・不等号・演算子など数学的に自然な位置で改行してください。
どちらの版にもmulticols、twocolumn、columnsなど外側の段組環境を追加してはいけません。長い内容をresizeboxや小さい文字で押し込まず、各行がその版の\linewidth内へ収まる構造にしてください。
問題が1件だけの場合もproblemsへ必ず1件格納してください。問題文以外の変換モードではproblemsを空配列にしてください。"#;

fn produces_problem_layout_variants(mode: &str) -> bool {
    matches!(
        mode,
        "problem"
            | "problem_with_subquestions"
            | "problem_bank_import"
            | "generate_problem_layouts"
    )
}

pub const BEGINNER_SOLUTION_INSTRUCTIONS: &str = r#"【解答モード：基礎から丁寧】
数学が苦手な高校生が一人で読み進められる解答にしてください。完成答案としての正確さを保ちながら、理解と再現のしやすさを標準モードより優先してください。

- 冒頭で、この問題が何を求めているか、与えられた条件から何が分かるか、最初にどこへ着目するかを平易な言葉で説明してください。
- 使用する公式・定理・基本事項は、名前だけを挙げず、必要な形を式で示し、今回なぜ使えるかを説明してください。高校で既習の内容でも、この問題の中心となる基本事項は省略しないでください。
- 新しい文字を置くときは何を表す文字かを明示し、文字の取り得る範囲や条件があればその場で説明してください。
- 式変形では、両辺に何をしたか、どの項を移項したか、何を代入したか、どの公式を使ったかが分かるように、非自明な変形を一段ずつ示してください。複数の操作をまとめて急に複雑な式を出さないでください。
- 因数分解、平方完成、通分、約分、分母を払う操作、両辺の2乗、平方根を取る操作、符号によって向きが変わる不等式変形は、必要な途中式と成り立つ条件を丁寧に記述してください。
- 「明らかに」「同様に」「計算すれば」だけで重要な過程を省略せず、初学者が同じ手順を自分で再現できる説明へ置き換えてください。
- 最後に、求めた値が問題の条件を満たすことや、最大・最小、必要十分性、場合分けの漏れなど、この問題で必要な確認を短く行ってから結論を書いてください。

ただし、単純な一桁の四則計算を過度に細分化したり、同じ説明を何度も繰り返したりせず、問題を解くために必要な基礎事項と式のつながりを丁寧に示してください。指定された段組の幅は守り、長くなる説明は短い段落と改行した数式へ分けてください。"#;

pub const TOPIC_METHOD_GUIDE_INSTRUCTIONS: &str = r#"【分野・解法の詳しい解説部品】
このモードでは、入力は単一の問題文ではなく、詳しく説明する高校数学の分野・単元・公式・解法・考え方と、必要に応じた重点の指定です。入力を問題として解答するのではなく、別の教材へそのまま挿入して繰り返し利用できる独立した解説部品を生成してください。

既存の解答・解説規則のうち、高校範囲、一般的な用語、記号、論理の正確さ、式変形の粒度、計算を簡単にする工夫、段組の幅、図の大きさ、式番号の形式はそのまま守ってください。一方、試験答案としての結論、問題固有の答え、最大3つの別解という構成は、この解説部品へ機械的に持ち込まないでください。複数の方法を扱うのは、使い分けの理解に本当に必要な場合だけにしてください。

出力は、次の見出しをこの順序でそれぞれ1回設けてください。見出しは教材内で見つけやすい「【概要】」等の表記とし、文書全体を支配する\section、\chapterやプリアンブルは生成しないでください。

1. 【概要】
   何を扱う分野・解法か、何を求める場面で役立つか、学習後に何ができるようになるかを短く示してください。
2. 【基本事項】
   理解に必要な定義、公式、前提条件、文字の範囲を高校生に分かる言葉と式で整理してください。公式は名前だけでなく形を示し、成り立つ条件を落とさないでください。
3. 【定石】
   問題のどの形・語句・条件へ着目すればこの方法を選べるか、方法の中心となる考え方、適用条件、使えない場合を一般化して説明してください。
4. 【手順】
   別の同型問題でも再現できるよう、着眼から結論の確認までを順序立てて説明してください。各段階で「何をするか」だけでなく「なぜそうするか」を示してください。
5. 【典型例】
   説明対象を理解するために必要十分な短い例を原則1題だけ作り、条件、途中式、判断理由、確認まで示してください。入力に例が指定されている場合はそれを優先し、無関係な数値例を水増ししないでください。
6. 【よくある誤り】
   適用条件の見落とし、符号・定義域・場合分け・同値性・計算上の典型的な誤りと、それを避ける確認方法を具体的に示してください。

分野名だけが入力された場合は、全範囲を浅く列挙せず、その分野の核となる見方と代表的な定石がつながる構成にしてください。特定の解法が入力された場合は、周辺分野の概説を長くせず、その解法を選ぶ目印、成立条件、手順、他の標準解法との使い分けへ重点を置いてください。
公式や手順を暗記項目として並べるだけでなく、式や条件のどの部分が判断の根拠になるかを説明してください。定義と公式、一般的な手順、典型例の数値を混同せず、一般論から例へ進み、例の結果を一般則のように書かないでください。
教材部品だけを読んでも理解できるようにしてください。ただし、入力されていない高度な発展内容や大学数学を追加して網羅性を装ってはいけません。高校範囲で説明できない指定が含まれる場合は推測せずwarningsへ記録してください。

latexには解説部品の本文だけを入れ、detectedTypeはpart、suggestedInsertTargetはpartにしてください。"#;

pub const BEGINNER_TOPIC_METHOD_GUIDE_INSTRUCTIONS: &str = r#"【分野・解法解説の説明レベル：基礎から丁寧】
数学が苦手な高校生が、この部品だけを読んで基本事項から手順までたどれる説明にしてください。
- 新しい用語や記号は初出で平易に説明し、前提知識を既習として省略しすぎないでください。
- 公式は文字式だけを示さず、各文字が何を表すか、いつ使えるか、式のどこを見るかを説明してください。
- 手順は一段ずつ示し、非自明な式変形では行った操作と理由を明記してください。
- 典型例では一般的な手順のどの段階を実行しているかが対応するように記述してください。
ただし、同じ定義や注意を複数の見出しで繰り返したり、自明な四則計算まで細分化したりせず、理解に必要な補足へ絞ってください。"#;

